function insightsPage(){const gaps=commonGaps(),students=teacherStudents(),attempts=db.results.length;$('#pageContent').innerHTML=`<div class="page-intro"><div><h3>Class learning insights</h3><p>Simple signals from assessment history to help guide your next lesson.</p></div><span class="pill">Rule-based prototype</span></div><div class="grid three">${statCard('⚑',gaps.filter(g=>g.rate>0).length,'Topics with learning gaps','Based on recent results','!')}${statCard('✓',attempts,'Assessments taken','Across your class','↗')}${statCard('♧',students.filter(s=>studentNeedsHelp(s.id).length).length,'Students flagged','At least one recent score below 70%','◎')}</div><div class="section-title"><div><h3>Topic-level signals</h3><p>Percent of demo students with a recent score below 70%.</p></div></div><div class="card table-wrap"><table><thead><tr><th>TOPIC</th><th>SUBJECT</th><th>STUDENTS NEEDING REVISION</th><th>RECOMMENDED ACTION</th></tr></thead><tbody>${gaps.map(g=>`<tr><td><b>${escapeHTML(g.topic.title)}</b></td><td>${g.topic.subject}</td><td><span class="score-badge ${g.rate>40?'warn':''}">${g.flagged}/${students.length} · ${g.rate}%</span></td><td>${g.flagged?'Re-teach with example + short check':'Keep practising; monitor future results'}</td></tr>`).join('')}</tbody></table></div><div class="card" style="margin-top:18px"><div class="card-head"><h3>How to use these insights</h3></div><div class="grid three"><div><span class="stat-icon">01</span><h4 style="font-size:12px;margin:12px 0 5px">Spot a pattern</h4><p class="subtle" style="line-height:1.6">Look for concepts where several students need more practice.</p></div><div><span class="stat-icon">02</span><h4 style="font-size:12px;margin:12px 0 5px">Revisit the basics</h4><p class="subtle" style="line-height:1.6">Use a worked example and a short classroom discussion.</p></div><div><span class="stat-icon">03</span><h4 style="font-size:12px;margin:12px 0 5px">Check again</h4><p class="subtle" style="line-height:1.6">Give another quick assessment and compare progress.</p></div></div></div>`;$('#pageContent').insertAdjacentHTML('beforeend',smartRecoveryTeacherSection(8));$('#pageContent').insertAdjacentHTML('beforeend',misconceptionInsightsHTML())}
function showAddStudent(){showModal(`<div class="modal-top"><div><h3>Add a local learner profile</h3><p class="muted">This adds a roster-only profile on this device. It does not create sign-in credentials; students must use the secure registration flow to create their own account.</p></div><button class="close-modal" onclick="closeModal()">✕</button></div><form id="addStudentForm"><div class="form-grid"><div class="field span2"><label>Student name</label><input name="name" required placeholder="e.g. Samira Patel"></div><div class="field"><label>Roll number</label><input name="id" required placeholder="e.g. LF1004"></div><div class="field"><label>Section</label><input name="section" value="A" maxlength="4"></div><div class="field"><label>Class</label><select name="className"><option>Class 6</option><option>Class 7</option><option selected>Class 8</option><option>Class 9</option><option>Class 10</option></select></div><div class="field"><label>School</label><input name="school" value="${escapeHTML(currentUser.school)}"></div></div><button class="btn primary full" type="submit">Add roster profile →</button></form>`);$('#addStudentForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),id=f.get('id').trim().toUpperCase();if(db.users.some(u=>u.id===id)){toast('That roll number already exists.');return}db.users.push({id,name:f.get('name').trim(),role:'student',className:f.get('className'),section:(f.get('section')||'A').trim().toUpperCase(),school:f.get('school')});saveDB();closeModal();studentsPage();toast(`Roster profile ${id} added on this device.`)}}
function exportMyProgress(){const rows=[['Date','Topic','Subject','Score','Correct','Total'],...allMyResults().map(r=>[new Date(r.date).toLocaleDateString(),r.topicTitle,r.subject,r.score,r.correct,r.total])];downloadCSV(rows,`${currentUser.id}-learnflex-progress.csv`)}
function downloadCSV(rows,name){const csv=rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);toast('Report exported.')}
