function friendlyExplanationHTML(topic){
 const intro={
  en:'Simple explanation',
  te:'Teluglish tip',
  hi:'Hinglish tip'
 }[currentLanguage]||'Simple explanation';
 const examples={
  fractions:{te:'Fraction ante whole lo oka part. Top number numerator, bottom number denominator. Same denominator unte top numbers add cheyyali.',hi:'Fraction matlab whole ka ek part. Same denominator ho toh numerators add karo; denominator same rahega.'},
  algebra:{te:'x ante manaki teliyani number. Equation lo rendu sides equal ga untayi; same operation rendu sides ki cheyyali.',hi:'x ek unknown number hai. Equation ke dono sides equal hote hain; jo operation ek side karte ho, doosri side par bhi karo.'},
  plants:{te:'Plants sunlight, water, carbon dioxide use chesi food tayaru chestayi. Ee process ni photosynthesis antaru.',hi:'Plants sunlight, water aur carbon dioxide se food banate hain. Is process ko photosynthesis kehte hain.'},
  ecosystems:{te:'Food chain lo energy oka living thing nunchi next thing ki move avutundi. Arrows energy direction chupistayi.',hi:'Food chain mein energy ek living thing se next tak jaati hai. Arrows energy ki direction dikhate hain.'},
  reading:{te:'Main idea ante passage mostly deni gurinchi cheptundo adi. Supporting details main idea ni explain chestayi.',hi:'Main idea matlab passage mainly kis baare mein hai. Supporting details us idea ko explain karte hain.'},
  civics:{te:'Community ante kalisi live, work, learn chese people. Shared rules andariki safe ga undadaniki help chestayi.',hi:'Community matlab log jo saath rehte, kaam karte ya seekhte hain. Shared rules sabko safe rakhne mein help karte hain.'}
 };
 if(currentLanguage==='en')return `<p class="pillar-note"><b>${intro}:</b> Read the explanation and example below. Use Read to listen.</p>`;
 const tip=(examples[topic.id]||{})[currentLanguage]||'';
 return `<div class="feedback-box good"><b>${intro}:</b> ${escapeHTML(tip)}<br><small>Key lesson content remains available in English to preserve subject terminology.</small></div>`;
}
function applyAccessibilityPreference(key,enabled){
 document.body.classList.toggle(key,enabled);
 try{localStorage.setItem('learnflex_access_'+key,enabled?'1':'0')}catch(e){}
}
function initAccessibility(){
 ['high-contrast','dyslexia-friendly','large-text'].forEach(key=>{
  const enabled=localStorage.getItem('learnflex_access_'+key)==='1';
  applyAccessibilityPreference(key,enabled);
  const btn=key==='high-contrast'?$('#contrastBtn'):key==='dyslexia-friendly'?$('#dyslexiaBtn'):$('#largeTextBtn');
  if(btn)btn.setAttribute('aria-pressed',String(enabled));
 });
 const contrast=$('#contrastBtn'),dyslexia=$('#dyslexiaBtn'),largeText=$('#largeTextBtn'),read=$('#readAloudBtn'),rate=$('#speechRateSelect');
 if(rate){rate.value=localStorage.getItem('learnflex_speech_rate')||'0.9';rate.onchange=()=>{localStorage.setItem('learnflex_speech_rate',rate.value);toast('Read-aloud speed updated')}}
 if(contrast)contrast.onclick=()=>{const on=!document.body.classList.contains('high-contrast');applyAccessibilityPreference('high-contrast',on);contrast.setAttribute('aria-pressed',String(on));toast(on?'High-contrast mode enabled':'High-contrast mode disabled')};
 if(dyslexia)dyslexia.onclick=()=>{const on=!document.body.classList.contains('dyslexia-friendly');applyAccessibilityPreference('dyslexia-friendly',on);dyslexia.setAttribute('aria-pressed',String(on));toast(on?'Reading-friendly display enabled':'Reading-friendly display disabled')};
 if(largeText)largeText.onclick=()=>{const on=!document.body.classList.contains('large-text');applyAccessibilityPreference('large-text',on);largeText.setAttribute('aria-pressed',String(on));toast(on?'Larger text enabled':'Larger text disabled')};
 if(read)read.onclick=()=>{
  if(!('speechSynthesis' in window)){toast('Read-aloud is not available in this browser.');return}
  if(window.speechSynthesis.speaking){window.speechSynthesis.cancel();read.textContent='🔊 Read';return}
  const target=$('#pageContent')||document.body;
  const textToRead=(target.innerText||'').trim().slice(0,12000);
  if(!textToRead){toast('There is no page text to read yet.');return}
  const utterance=new SpeechSynthesisUtterance(textToRead);
  utterance.rate=Number(localStorage.getItem('learnflex_speech_rate')||0.9);
  const lang=currentLanguage==='te'?'te-IN':currentLanguage==='hi'?'hi-IN':'en-IN';
  utterance.lang=lang;utterance.onend=()=>read.textContent='🔊 Read';utterance.onerror=()=>read.textContent='🔊 Read';
  read.textContent='⏹ Stop';window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance);
 };
}
