let serverSyncTimer=null, syncingFromServer=false, backendConnected=false, backendSyncInProgress=false;
let activeLessonModes={};

function ensureLearnFlexContent(){
 const t=db.topics.find(x=>x.id==='fractions');
 // Retain the legacy question ID for saved-progress compatibility; it is not a product brand.
 if(t&&!t.questions.some(q=>q.id==='saathi-fraction-denominator-diagnostic')){
  t.questions.push({id:'saathi-fraction-denominator-diagnostic',q:'What is 1/2 + 1/4?',options:['2/6','3/4','2/4','1/4'],answer:1,explain:'Write 1/2 as 2/4. Then 2/4 + 1/4 = 3/4. The parts must have the same-sized denominator before you add them.',misconceptionByOption:{0:'fraction_add_denominators',2:'fraction_add_numerators_only',3:'fraction_keep_first_term'}});
 }
 // Add stable IDs and metadata to existing questions without overwriting user records.
 db.topics.forEach(topic=>topic.questions.forEach((q,i)=>{if(!q.id)q.id=`${topic.id}-q${i+1}`}));
 saveDB();
}
function diagnoseMisconception(topicId,q,selectedIndex){
 if(!Number.isInteger(selectedIndex)||selectedIndex===q.answer)return null;
 const topic=db&&db.topics?db.topics.find(x=>x.id===topicId):null;
 const selected=(q.options||[])[selectedIndex]||'';
 const preset=q.misconceptionByOption&&q.misconceptionByOption[selectedIndex];
 const map={
  fraction_add_denominators:{label:'Adding denominators as well as numerators',explanation:'This answer can suggest that the bottom numbers were added too. First rewrite both fractions with the same denominator, then add only the top numbers.',action:'Use fraction bars to show fourths and practise one equivalent-fraction example.'},
  fraction_add_numerators_only:{label:'Keeping the original denominator without making equal-sized parts',explanation:'The fractions have different-sized parts. Rewrite 1/2 as 2/4 before combining it with 1/4.',action:'Compare one-half and two-fourths visually before adding.'},
  fraction_keep_first_term:{label:'Using only part of the expression',explanation:'Both fractions contribute to the total. Convert to equal-sized parts, then combine both numerators.',action:'Mark the two fractions in different colours and count all the shaded parts.'}
 };
 let key=preset;
 const qtxt=(q.q||'').toLowerCase();
 if(!key&&topicId==='fractions'){
  if(/1\/2\s*\+\s*1\/4/.test(qtxt)&&selected==='2/6')key='fraction_add_denominators';
  else if(/1\/2\s*\+\s*1\/4/.test(qtxt)&&selected==='2/4')key='fraction_add_numerators_only';
  else if(/1\/2\s*\+\s*1\/4/.test(qtxt)&&selected==='1/4')key='fraction_keep_first_term';
  else if(/\+/.test(qtxt)&&/\/(\d+)/.test(selected)&&qtxt.includes('/'))key='fraction_add_denominators';
 }
 let result=map[key];
 if(!result&&topicId==='algebra'){
  result={label:'Operation or equation-balance check',explanation:'This choice may mean the operation needed to isolate the variable is not clear yet. Apply the same inverse operation to both sides and check the result.',action:'Work one equation slowly, writing the operation on both sides.'};
 }
 if(!result&&topicId==='plants'){
  result={label:'Photosynthesis input/output check',explanation:'This answer may mix up what the plant takes in with what it makes or releases. Review sunlight, water and carbon dioxide as inputs, and glucose and oxygen as outputs.',action:'Sort the key words into “used” and “made/released”.'};
 }
 if(!result&&topicId==='ecosystems'){
  result={label:'Food-chain role or energy-direction check',explanation:'This choice may confuse the role of an organism or the direction shown by the arrows. Producers make food; arrows show the direction energy moves.',action:'Read the chain from the food source to the organism receiving energy.'};
 }
 if(!result&&topicId==='reading'){
  result={label:'Main idea versus detail check',explanation:'This choice may focus on a small detail rather than what the whole passage is mostly about.',action:'Say the passage in one sentence, then compare that sentence with the options.'};
 }
 if(!result&&topicId==='civics'){
  result={label:'Shared-resource or community-role check',explanation:'This choice may overlook how shared rules and public services help people use common spaces safely.',action:'Think about who can use the resource and how it supports the community.'};
 }
 if(!result)return null;
 return {key:key||`${topicId}_concept_check`,label:result.label,explanation:result.explanation,action:result.action,selectedAnswer:selected,topicId,topicTitle:topic?topic.title:topicId,question:q.q};
}
function misconceptionHTML(topicId,q,selectedIndex){
 const d=diagnoseMisconception(topicId,q,selectedIndex);if(!d)return '';
 return `<div class="diagnostic-card"><div class="diagnostic-kicker">MISCONCEPTION DETECTIVE · POSSIBLE SIGNAL</div><b>${escapeHTML(d.label)}</b><p>${escapeHTML(d.explanation)}</p><small><b>Try next:</b> ${escapeHTML(d.action)}</small><div class="subtle" style="margin-top:8px">This is a rule-based learning hint from one answer, not a diagnosis of the student.</div></div>`;
}
