  algebra:{en:'Variable · equation',te:'చరరాశి · సమీకరణం (Chararashi · Sameekaranam)',hi:'Variable · equation mein anjaan number'},
  plants:{en:'Photosynthesis · chlorophyll',te:'కిరణజన్య సంయోగక్రియ · క్లోరోఫిల్',hi:'Photosynthesis · patton ka hara chlorophyll'},
  ecosystems:{en:'Producer · consumer · food chain',te:'ఉత్పత్తిదారు · వినియోగదారు · ఆహార గొలుసు',hi:'Producer · consumer · food chain'},
  reading:{en:'Main idea · supporting details',te:'ప్రధాన భావం · సహాయక వివరాలు',hi:'Main idea · usko samjhane wale details'},
