function lessonSteps(topic){
 const steps={
  fractions:['Make both denominators equal.','Rewrite 1/2 as 2/4.','Add numerators: 2 + 1 = 3.','Keep denominator 4: result = 3/4.'],
  algebra:['Find the operation applied to the variable.','Use the inverse operation on both sides.','Simplify the number side.','Check by substituting the answer into the original equation.'],
  plants:['Leaves capture light using chlorophyll.','Roots absorb water; leaves take in carbon dioxide.','The plant uses light energy to make glucose.','Oxygen is released as a by-product.'],
  ecosystems:['Identify the producer.','Find which organism eats it.','Follow arrows in the direction energy moves.','Explain how each organism depends on the previous one.'],
  reading:['Read the complete passage.','Ask what the whole text is mostly about.','Separate the main idea from small details.','Choose details that directly support the main idea.'],
  civics:['Identify the people in the community.','Notice each person or service’s role.','Find the shared rules and resources.','Explain how they help people cooperate safely.']
 };
 return steps[topic.id]||['Read the explanation.','Study the worked example.','Try a practice question.','Review the feedback and try a new example.'];
}
